// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.facadeimport timber.log.Timberimport android.app.Activityimport android.content.Contextimport com.roshan.persona.productivity.alarm.AlarmPermissionsHelperimport com.roshan.persona.productivity.calendar.CalendarPermissionHandler/** * NOUS — Productivity Permission Flow (Module 14 v1.2 — Step 14.5). * * Single coordinator that knows about ALL permissions the productivity * stack needs: *   - SCHEDULE_EXACT_ALARM (API 31+) — for setAlarmClock + setExactAndAllowWhileIdle *   - USE_EXACT_ALARM (API 34+) — alternative to SCHEDULE_EXACT_ALARM *   - POST_NOTIFICATIONS (API 33+) — for alarm/timer/reminder notifications *   - READ_CALENDAR — for calendar read operations *   - WRITE_CALENDAR — for calendar write operations * * ## Why a coordinator? * * Per strategy v1.1 §"Improvement 1: Runtime Permission Flow": * ``` * User says "7 baje alarm lagao" → *   Brain routes to ProductivitySkill → *     ProductivityFacade.setAlarm() → *       check SCHEDULE_EXACT_ALARM permission → *         if missing → return NeedsPermission(["android.permission.SCHEDULE_EXACT_ALARM"]) → *           Brain emits SkillNeedsPermission event → *             UI shows permission dialog → *               user grants → *                 retry setAlarm() * ``` * * The facade delegates the actual permission CHECK to the per-engine * helpers ([AlarmPermissionsHelper], [CalendarPermissionHandler]). This * class is the UI-facing coordinator that knows how to REQUEST all of * them in the right order. * * ## Permission Request Order * * 1. POST_NOTIFICATIONS (runtime dialog — easiest, always needed) * 2. SCHEDULE_EXACT_ALARM (Settings page — needed for alarms/timers) * 3. READ_CALENDAR + WRITE_CALENDAR (runtime dialog — only if user uses calendar) * * The order matters: POST_NOTIFICATIONS is the most universally useful * permission (every productivity operation shows a notification). If the * user denies it, the others don't matter much. * * @see <a href="docs/strategy/module-14-productivity-strategy-v1.2-final.md">§Improvement 1</a> */class ProductivityPermissionFlow(    context: Context,    private val alarmPermissions: AlarmPermissionsHelper = AlarmPermissionsHelper(context),    private val calendarPermissions: CalendarPermissionHandler = CalendarPermissionHandler(context),) {    companion object {        private const val TAG = "ProductivityPerms"        /**         * All permissions the productivity stack might need.         *         * UI can use this to show a single "Grant all permissions" button.         */        val ALL_PERMISSIONS: List<String> = listOf(            android.Manifest.permission.POST_NOTIFICATIONS,            android.Manifest.permission.READ_CALENDAR,            android.Manifest.permission.WRITE_CALENDAR,            // SCHEDULE_EXACT_ALARM is requested via Settings, not runtime dialog.            // USE_EXACT_ALARM is granted at install time if declared in manifest.        )        /** Request code for runtime permission dialog (POST_NOTIFICATIONS + CALENDAR). */        const val REQUEST_CODE_RUNTIME_PERMISSIONS = 14001        /** Request code for SCHEDULE_EXACT_ALARM Settings page. */        const val REQUEST_CODE_EXACT_ALARM_SETTINGS = 14002    }    /**     * Get the full permission state for the productivity stack.     *     * @return [ProductivityPermissionState] with all permission flags.     */    fun getPermissionState(): ProductivityPermissionState {        return ProductivityPermissionState(            canScheduleExactAlarms = alarmPermissions.canScheduleExactAlarms(),            hasUseExactAlarmPermission = alarmPermissions.hasUseExactAlarmPermission(),            canPostNotifications = alarmPermissions.canPostNotifications(),            hasReadCalendar = calendarPermissions.hasReadCalendarPermission(),            hasWriteCalendar = calendarPermissions.hasWriteCalendarPermission(),        )    }    /**     * Get a list of all missing permissions for a given operation type.     *     * @param operationType the operation the user wants to perform.     * @return list of missing permission strings (empty if all granted).     */    fun getMissingPermissions(operationType: ProductivityOperationType): List<String> {        return when (operationType) {            ProductivityOperationType.ALARM,            ProductivityOperationType.TIMER -> {                val missing = mutableListOf<String>()                if (!alarmPermissions.canSetExactAlarms()) {                    missing.add("android.permission.SCHEDULE_EXACT_ALARM")                }                if (!alarmPermissions.canPostNotifications()) {                    missing.add(android.Manifest.permission.POST_NOTIFICATIONS)                }                missing            }            ProductivityOperationType.REMINDER -> {                val missing = mutableListOf<String>()                if (!alarmPermissions.canPostNotifications()) {                    missing.add(android.Manifest.permission.POST_NOTIFICATIONS)                }                missing            }            ProductivityOperationType.NOTE -> {                // Notes don't need runtime permissions (encrypted DB only).                emptyList()            }            ProductivityOperationType.CALENDAR_READ -> {                calendarPermissions.getMissingReadPermissions()            }            ProductivityOperationType.CALENDAR_WRITE -> {                calendarPermissions.getMissingWritePermissions()            }        }    }    /**     * Get a user-friendly message about missing permissions for an operation.     */    fun getMissingPermissionsMessage(operationType: ProductivityOperationType): String {        val missing = getMissingPermissions(operationType)        if (missing.isEmpty()) return ""        return buildString {            if ("android.permission.SCHEDULE_EXACT_ALARM" in missing) {                append("I need exact alarm permission to set alarms at the right time. ")                append("Please enable it in Settings. ")            }            if (android.Manifest.permission.POST_NOTIFICATIONS in missing) {                append("I need notification permission to show you when the alarm fires. ")            }            if (android.Manifest.permission.READ_CALENDAR in missing) {                append("I need calendar read permission to see your events. ")            }            if (android.Manifest.permission.WRITE_CALENDAR in missing) {                append("I need calendar write permission to create events. ")            }        }.trim()    }    /**     * Request all runtime permissions needed for an operation (REAL Android flow).     *     * This launches the system permission dialog for POST_NOTIFICATIONS + CALENDAR.     * SCHEDULE_EXACT_ALARM requires a separate Settings page launch (see     * [requestExactAlarmPermission]).     *     * @param activity      the current Activity.     * @param operationType the operation the user wants to perform.     * @return true if any runtime permission dialog was launched.     */    fun requestRuntimePermissions(        activity: Activity,        operationType: ProductivityOperationType,    ): Boolean {        val missing = getMissingPermissions(operationType)            .filter { it != "android.permission.SCHEDULE_EXACT_ALARM" }  // Skip Settings-only.        if (missing.isEmpty()) return false        val toRequest = missing.toTypedArray()        Timber.tag(TAG).i("Requesting runtime permissions: ${toRequest.toList()}.")        // REAL Android runtime permission request.        activity.requestPermissions(toRequest, REQUEST_CODE_RUNTIME_PERMISSIONS)        return true    }    /**     * Launch the SCHEDULE_EXACT_ALARM Settings page (REAL Android flow).     *     * Needed because SCHEDULE_EXACT_ALARM cannot be requested via the runtime     * dialog — the user must manually toggle it in Settings.     */    fun requestExactAlarmPermission(activity: Activity): Boolean {        return alarmPermissions.requestExactAlarmPermission(activity)    }    /**     * Open the app's Settings page for calendar permissions (used when user     * has permanently denied the runtime dialog).     */    fun openCalendarSettings(activity: Activity): Boolean {        return calendarPermissions.openCalendarSettings(activity)    }    /**     * Check if the productivity stack is fully permissioned for an operation.     */    fun hasAllPermissions(operationType: ProductivityOperationType): Boolean {        return getMissingPermissions(operationType).isEmpty()    }}/** * Operation type for permission checking. * * Different operations need different permissions: *   - ALARM / TIMER → SCHEDULE_EXACT_ALARM + POST_NOTIFICATIONS *   - REMINDER → POST_NOTIFICATIONS (WorkManager handles its own wake) *   - NOTE → none (encrypted DB only) *   - CALENDAR_READ → READ_CALENDAR *   - CALENDAR_WRITE → WRITE_CALENDAR */enum class ProductivityOperationType(val displayName: String) {    ALARM("Alarm"),    TIMER("Timer"),    REMINDER("Reminder"),    NOTE("Note"),    CALENDAR_READ("Calendar Read"),    CALENDAR_WRITE("Calendar Write"),}/** * Full permission state for the productivity stack. * * UI can display this in Settings → Permissions. */data class ProductivityPermissionState(    val canScheduleExactAlarms: Boolean,    val hasUseExactAlarmPermission: Boolean,    val canPostNotifications: Boolean,    val hasReadCalendar: Boolean,    val hasWriteCalendar: Boolean,) {    /** True if alarms can be set (SCHEDULE_EXACT_ALARM OR USE_EXACT_ALARM). */    val canSetAlarms: Boolean get() = canScheduleExactAlarms || hasUseExactAlarmPermission    /** True if reminders can be set (just POST_NOTIFICATIONS). */    val canSetReminders: Boolean get() = canPostNotifications    /** True if calendar can be read. */    val canReadCalendar: Boolean get() = hasReadCalendar    /** True if calendar can be written. */    val canWriteCalendar: Boolean get() = hasWriteCalendar    /** True if all calendar operations are allowed. */    val hasFullCalendarAccess: Boolean get() = hasReadCalendar && hasWriteCalendar    /** True if everything is granted (for "Grant all" UI). */    val allGranted: Boolean get() =        canSetAlarms && canPostNotifications && hasFullCalendarAccess}